<script setup lang="ts">import {fmt} from '../utils/format';defineProps<{result:any;limit?:number}>();function codeFor(result:any,name:string){const entry=(result.category_entries||[]).find((e:any)=>e.name===name);return entry?.code||''}</script><template><section class="vote-matrix"><header><strong>逐票图谱 / 前{{Math.min(limit||12,result.items.length)}}试样</strong><span>同一试样的三票保持在一行；悬停可见稳定编码</span></header><div class="vote-scroll"><div class="vote-grid"><div class="vote-grid-head"><span>试样编号</span><span v-for="r in result.raters" :key="r">{{r}}</span><span>逐项 Pᵢ</span></div><div class="vote-row" v-for="item in result.items.slice(0,limit||12)" :key="item.id"><strong>{{item.reference}}</strong><span v-for="v in item.votes" :key="v.rater" :class="['vote-cell','category-'+result.categories.indexOf(v.category)]" :title="v.category_code||codeFor(result,v.category)||'未编码'">{{v.category}}<small v-if="v.category_code" class="code-chip">{{v.category_code}}</small></span><em>{{fmt(item.agreement,3)}}</em></div></div></div></section></template>
